import requests
urls={
'ACOG':'https://www.acog.org/clinical/clinical-guidance/obstetric-care-consensus/articles/2018/12/placenta-accreta-spectrum',
'FIGO_PubMed':'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term=placenta+accreta+spectrum+cesarean+hysterectomy+34+35+weeks&retmode=json&retmax=5'
}
for k,u in urls.items():
    try:
        r=requests.get(u,timeout=15)
        print(k, r.status_code, len(r.text))
        print(r.text[:500].replace('\n',' '))
    except Exception as e: print(k,e)
